// Build-time bundler for DepHub.
//
// Reads every tracked file from .github/dephub-games.json, inlines each
// module's source into a single Lua table, and rewrites DepHub.lua so its
// httpGet() resolves from that in-memory table instead of the network.
//
// The result is one self-contained Lua chunk: the private repository's source
// never has to be reachable at runtime, so the repo can stay private and only
// the (optionally obfuscated) bundle is what ships.
//
// Usage: node tools/bundle.js <repoRoot> <outFile>

const fs = require('node:fs');
const path = require('node:path');

const root = process.argv[2];
const outFile = process.argv[3];
if (!root || !outFile) {
  console.error('Usage: node tools/bundle.js <repoRoot> <outFile>');
  process.exit(1);
}

const configPath = path.join(root, '.github/dephub-games.json');
const loaderPath = path.join(root, 'DepHub.lua');
const versionPath = path.join(root, 'src/version.txt');

const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
const loader = fs.readFileSync(loaderPath, 'utf8');
const version = fs.readFileSync(versionPath, 'utf8').trim();

// The union of every tracked file across all games is the set of modules the
// bundle carries. DepHub.lua is the host (skip it); version.txt is kept so any
// module that re-checks the version resolves offline.
const modulePaths = new Set();
for (const game of Object.values(config)) {
  for (const file of game.files) {
    if (file === 'DepHub.lua') continue;
    modulePaths.add(file);
  }
}

// The manifest only lists per-game feature files, but the loader also routes to
// files that appear in no game entry (the universal fallback, core support, and
// each target's Core path which a per-game list may not mention). Bundle
// everything the loader can reach, otherwise those routes bypass
// BUNDLED_SOURCES and hit the network — which a private repository cannot
// serve.
const routedCores = new Set();
for (const match of loader.matchAll(/Core\s*=\s*"([^"]+)"/g)) routedCores.add(match[1]);
for (const core of routedCores) modulePaths.add(core);

// Walk src/ recursively: any module under it is potentially loadable, so inline
// the lot. This is the belt-and-braces guarantee that no route falls through to
// the network, and it means new files need no manifest edit to ship.
function walk(dir) {
  for (const entry of fs.readdirSync(path.join(root, dir), {withFileTypes: true})) {
    const rel = dir + '/' + entry.name;
    if (entry.isDirectory()) walk(rel);
    else if (entry.name.endsWith('.lua') || entry.name.endsWith('.txt')) modulePaths.add(rel);
  }
}
walk('src');
modulePaths.add('src/version.txt');

const sources = {};
for (const p of [...modulePaths].sort()) {
  const full = path.join(root, p);
  if (!fs.existsSync(full)) throw new Error('Missing module: ' + p);
  let text = fs.readFileSync(full, 'utf8');
  // Rewrite direct game:HttpGet / game.HttpGet calls to the bundle's safe
  // resolver. Executors differ: some expose HttpGet only as a global, and
  // writing a DataModel member may error. Call sites must not depend on the
  // member existing. moduleName is used only for the error message.
  text = text
    .replace(/game:HttpGet\(/g, '__dephubHttpGet(')
    .replace(/game\.HttpGet\(/g, '__dephubHttpGet(');
  sources[p] = text;
}

// Encode each source as a Lua long-bracket string. Lua's [==[ ]==] tolerates
// embedded brackets as long as the level is high enough; pick a level the
// source itself does not contain.
function luaLongString(text, name) {
  let level = 0;
  for (;;) {
    const open = '[' + '='.repeat(level) + '[';
    const close = ']' + '='.repeat(level) + ']';
    if (!text.includes(close)) return open + '\n' + text + '\n' + close;
    level += 1;
    if (level > 12) throw new Error('Could not bracket-encode ' + name);
  }
}

const tableLines = [];
for (const [p, source] of Object.entries(sources)) {
  tableLines.push('    [' + JSON.stringify(p) + '] = ' + luaLongString(source, p) + ',');
}

// Inject the bundled table at the top of the loader and short-circuit httpGet.
const bundleHeader = [
  '-- DepHub bundled build. Source revision ' + version + '.',
  '-- Generated by tools/bundle.js. Do not edit by hand.',
  'local BUNDLED_SOURCES = {',
  tableLines.join('\n'),
  '}',
  '',
  '-- Safe HttpGet resolver. Modules never call game:HttpGet directly: some',
  '-- executors expose HttpGet only as a global, and writing a DataModel member',
  '-- that does not exist errors. Resolve bundled paths from the in-memory table',
  '-- first, then fall back to whatever fetch primitive the executor provides.',
  '--',
  '-- Published on every shared environment a dynamically-compiled module can',
  '-- see: backends and features are compiled with loadstring and run outside',
  '-- this chunk, so a chunk-local resolver would be invisible to them. On a real',
  '-- executor getgenv(), _G and the chunk environment are the same table; in a',
  '-- test harness they can differ, so all three are written.',
  'local __dephubEnvs = {_G}',
  'if type(getgenv) == "function" then',
  '    local shared = getgenv()',
  '    if type(shared) == "table" then __dephubEnvs[#__dephubEnvs + 1] = shared end',
  'end',
  'local globalHttpGet = (type(HttpGet) == "function") and HttpGet or nil',
  'local function __dephubResolve(url)',
  '    if type(url) ~= "string" then return nil end',
  '    local clean = url:match("^[^?]*") or url',
  '    local rel = clean:match("DepHub/[^/]+/(.+)$")',
  '    if rel and type(BUNDLED_SOURCES[rel]) == "string" then return BUNDLED_SOURCES[rel] end',
  '    for _, shared in ipairs(__dephubEnvs) do',
  '        local table_ = shared.__DEPHUB_BUNDLED_SOURCES',
  '        if type(table_) == "table" and rel and type(table_[rel]) == "string" then return table_[rel] end',
  '    end',
  '    if type(globalHttpGet) == "function" then return globalHttpGet(url) end',
  '    local memberOk, member = pcall(function() return game.HttpGet end)',
  '    if memberOk and type(member) == "function" then',
  '        local ok, result = pcall(function() return game:HttpGet(url) end)',
  '        if ok then return result end',
  '    end',
  '    return nil',
  'end',
  'local __dephubHttpGet = __dephubResolve',
  '-- Publish to every shared environment so loadstring-compiled modules resolve',
  '-- the rewritten call sites without a setfenv.',
  'for _, shared in ipairs(__dephubEnvs) do',
  '    shared.__dephubHttpGet = __dephubResolve',
  '    shared.__DEPHUB_HTTP_GET = __dephubResolve',
  '    shared.__DEPHUB_BUNDLED_SOURCES = BUNDLED_SOURCES',
  'end',
  ''
].join('\n');

// Rewrite httpGet to serve from BUNDLED_SOURCES first. The original fetches
// BASE_URL .. path; when the request finds nothing locally it still falls back
// to the network, which keeps the updater/marker paths working or failing
// gracefully instead of hard-erroring.
const originalHttpGet = `local function httpGet(path, useCache)
    local cache = getCache()
    if useCache ~= false and type(cache[path]) == "string" and #cache[path] > 0 then return true, cache[path] end
    local ok, result = performRequest(BASE_URL .. path)
    if not ok then return false, result end
    if useCache ~= false then cache[path] = result end
    return true, result
end`;

const bundledHttpGet = `local function httpGet(path, useCache)
    local bundled = BUNDLED_SOURCES[path]
    if type(bundled) == "string" and #bundled > 0 then return true, bundled end
    local cache = getCache()
    if useCache ~= false and type(cache[path]) == "string" and #cache[path] > 0 then return true, cache[path] end
    local ok, result = performRequest(BASE_URL .. path)
    if not ok then return false, result end
    if useCache ~= false then cache[path] = result end
    return true, result
end`;

if (!loader.includes(originalHttpGet)) {
  throw new Error('Could not locate httpGet() in DepHub.lua — loader layout changed.');
}

let bundled = loader.replace(originalHttpGet, bundledHttpGet);
// Prepend the table declaration after the initial file-local aliases so it
// sits at the top of the generated chunk.
const injectionPoint = 'local env = type(getgenv) == "function" and getgenv() or _G\n';
if (!bundled.includes(injectionPoint)) {
  throw new Error('Could not find loader injection point.');
}
bundled = bundled.replace(injectionPoint, injectionPoint + '\n' + bundleHeader + '\n');

// Backends fetch their own feature files with game:HttpGet(BASE_URL .. path),
// bypassing the loader's httpGet. Wrap game.HttpGet so any request that maps to
// a bundled path is served locally, keeping the bundle fully self-contained.
const httpWrapMarker = 'local placeId = tostring(game.PlaceId)';
if (!bundled.includes(httpWrapMarker)) {
  throw new Error('Could not find game.HttpGet wrap point.');
}
const httpWrap = [
  '-- Serve backend-initiated game:HttpGet calls from the bundle when possible.',
  '-- Feature/quest files a backend fetches directly (rather than through the',
  '-- loader httpGet) resolve here, so the bundle never needs the network. Any',
  '-- cache-busting query string is stripped before the lookup.',
  '--',
  '-- Not every executor exposes HttpGet as a DataModel member: some provide it',
  '-- only as a global, and writing a nonexistent member errors. So probe before',
  '-- wrapping, and fall back to the global helper when the member is absent.',
  'do',
  '    local bundledFor = function(url)',
  '        if type(url) ~= "string" then return nil end',
  '        local clean = url:match("^[^?]*") or url',
  '        local rel = clean:match("DepHub/[^/]+/(.+)$")',
  '        if rel and BUNDLED_SOURCES[rel] then return BUNDLED_SOURCES[rel] end',
  '        return nil',
  '    end',
  '    local memberOk, nativeHttpGet = pcall(function() return game.HttpGet end)',
  '    if memberOk and type(nativeHttpGet) == "function" then',
  '        if pcall(function() game.HttpGet = nativeHttpGet end) then',
  '            local ok, err = pcall(function()',
  '                game.HttpGet = function(a, b, ...)',
  '                    local url = (b ~= nil) and b or a',
  '                    local self = (b ~= nil) and a or game',
  '                    local hit = bundledFor(url)',
  '                    if hit then return hit end',
  '                    return nativeHttpGet(self, url, ...)',
  '                end',
  '            end)',
  '            if not ok then game.HttpGet = nativeHttpGet end',
  '        end',
  '    elseif type(HttpGet) == "function" then',
  '        -- No DataModel member: install a global shim for backends that call',
  '        -- HttpGet(url) directly, and a game:HttpGet method on the metatable of',
  '        -- a proxy is not possible here, so also expose it as game.HttpGet only',
  '        -- when the engine accepts the write (checked above).',
  '        local nativeGlobal = HttpGet',
  '        local shim = function(a, b, ...)',
  '            local url = (b ~= nil) and b or a',
  '            if type(url) ~= "string" then url = a end',
  '            local hit = bundledFor(url)',
  '            if hit then return hit end',
  '            return nativeGlobal(url, ...)',
  '        end',
  '        if pcall(function() game.HttpGet = shim end) then',
  '            game.HttpGet = shim',
  '        end',
  '        HttpGet = shim',
  '    end',
  'end',
  ''
].join('\n');bundled = bundled.replace(httpWrapMarker, httpWrap + '\n' + httpWrapMarker);

fs.mkdirSync(path.dirname(outFile), { recursive: true });
fs.writeFileSync(outFile, bundled, 'utf8');

console.log('bundled ' + Object.keys(sources).length + ' modules -> ' + outFile);
